import{_ as l,l as o,o as r,c,v as e,p as s,x as t,d as n,i as h,S as d}from"./chunks/framework.InCnrqk-.js";const D=JSON.parse('{"title":"关键面积","description":"","frontmatter":{"title":"关键面积","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/critical-area.md","filePath":"litho/critical-area.md","lastUpdated":1789023840000}'),p={name:"litho/critical-area.md"};function m(A,a,_,E,B,u){const i=o("Mermaid");return r(),c("div",null,[a[1]||(a[1]=e('<h1 id="关键面积" tabindex="-1">关键面积 <a class="header-anchor" href="#关键面积" aria-label="Permalink to &quot;关键面积&quot;">​</a></h1><div class="epigraph"><p>同样大小的颗粒，落在密线缝里会桥，落在空白里无事；关键面积把版图与缺陷尺寸合成「能杀死管芯的那部分面积」。</p><footer>—— 对照 Maly 等对 critical area 的论述；IC 良率对布局灵敏度的通称</footer></div><p><a href="/litho/yield-models">上一课</a>用 \\(DA\\) 做账。缺口是 \\(A\\) 不是芯片外形面积：只有能造成短路、开路、via 失效的几何才算。<a href="/litho/design-rule-origin">设计规则起源</a> 已说规则是失效代理；本课钉关键面积（critical area）计算。系统热点对随机颗粒，留给[下一课](/litho/systematic-vs-random-defects）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>关键面积 \\(A_\\mathrm{cr}(r)\\) 对缺陷半径 \\(r\\) 积分，再与尺寸分布相乘得失败率。密金属、小 tip、via 覆盖不足让 \\(A_\\mathrm{cr}\\) 膨胀——同一洁净度下良率更差。冗余 via、加宽、放宽 tip 是用面积换良率，与 LFD 的可印性谈判叠在一起。</p><p>缺口是<strong>布局灵敏度</strong>，不是再拟合负二项。DTCO 加轨或加 dummy 会改 \\(A_\\mathrm{cr}\\)，也改刻蚀负载，账要联立。</p><h3 id="光刻系统失效不是颗粒关键面积" tabindex="-1">光刻系统失效不是颗粒关键面积 <a class="header-anchor" href="#光刻系统失效不是颗粒关键面积" aria-label="Permalink to &quot;光刻系统失效不是颗粒关键面积&quot;">​</a></h3><p>OPC 热点在每颗管芯同一地点桥连，关键面积公式假定缺陷位置随机。系统失效应单列，否则 \\(D\\) 会被估爆，洁净室会去抓不存在的颗粒。</p><p><span class="marginnote">缺陷尺寸分布通常来自检测，有漏检。\\(A_\\mathrm{cr}\\) 对小 \\(r\\) 敏感，而小缺陷恰是光学检测最弱处——电子束课会补。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>提取：对每层做短路/开路关键面积（多边形膨胀–重叠一类算法）。输入：缺陷尺寸分布。输出：按层的失败率贡献，指导哪层该加冗余 via 或放宽。与 SRAM：阵列 \\(A_\\mathrm{cr}\\) 极高且周期，单独算。与 via 协同：enclosure 进入开路关键面积。</p><p>尺寸分布要用复检校准后的检测数据，并声明漏检。Maly 的 critical area 是布局灵敏度；输入错了，冗余 via 会加在错误的层上。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>半径 \\(r\\) 的圆（或方）缺陷，若其落点使两导体间距 \\(\\lt\\) 2r 则短路。积分对间距分布敏感，故最小间隔规则直接杠杆 \\(A_\\mathrm{cr}\\)。多重图形的异色间距还含套刻，有效间隔随机化，关键面积要用套刻分布卷积——EPE 预算在良率上的样子。</p>',14)),(r(),s(d,null,{default:t(()=>[h(i,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20LAY%5B%22%E5%A4%9A%E8%BE%B9%E5%BD%A2%22%5D%20--%3E%20CA%5B%22A_cr(r)%22%5D%0A%20%20DIST%5B%22%E7%BC%BA%E9%99%B7%E5%B0%BA%E5%AF%B8%E5%88%86%E5%B8%83%22%5D%20--%3E%20Y%5B%22%E9%9A%8F%E6%9C%BA%E9%A2%97%E7%B2%92%E5%A4%B1%E8%B4%A5%E7%8E%87%22%5D%0A%20%20CA%20--%3E%20Y%0A%20%20SYS%5B%22%E7%B3%BB%E7%BB%9F%E7%83%AD%E7%82%B9%22%5D%20--%3E%20SEP%5B%22%E5%8D%95%E7%8B%AC%E5%88%97%E8%B4%A6%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<p>系统热点单列，不并进 A_cr D。缺陷尺寸分布必须经复检校准，否则冗余 via 会加错层。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>计算不替代硅上检测。不把某 EDA 关键面积模块当物理定律。颗粒形状不是圆，模型是工程近似。</p><p>后课默认：随机颗粒良率用关键面积加权。下一课强制把系统图形化失效从 \\(D\\) 里拆走。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>关键面积是布局对随机缺陷的灵敏度，不是芯片外形。</li><li>系统热点不可并进 \\(A_\\mathrm{cr}D\\)。</li><li>冗余 via 与 tip 规则直接杠杆 \\(A_\\mathrm{cr}\\)。</li><li>套刻使异色间距随机化，关键面积要对 EPE 卷积。</li><li>出处：Maly critical area；IC 布局良率灵敏度通称。</li></ul>',6))])}const P=l(p,[["render",m]]);export{D as __pageData,P as default};
